                post_hook={
                    "sql": "create or replace table maplemonk.beastlife_MetaDOD_Table as WITH main_data AS ( WITH shopy AS ( WITH fb AS ( SELECT DATE, CAMPAIGN_NAME, CAMPAIGN_ID, AD_NAME, AD_ID, ADSET_NAME, SUM(SPEND) AS SPEND, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS, SUM(Link_Clicks) AS Link_Clicks, SUM(ADD_TO_CARTS) AS ADD_TO_CARTS, SUM(ADD_TO_CART_VALUE) AS ADD_TO_CART_VALUE, SUM(LANDING_PAGE_VIEWS) AS LANDING_PAGE_VIEWS, SUM(INITIATE_CHECKOUTS) AS INITIATE_CHECKOUTS, SUM(INITIATE_CHECKOUTS_VALUE) AS INITIATE_CHECKOUTS_VALUE, SUM(one_day_click_conversions) AS one_day_click_conversions, SUM(one_day_click_conversion_value) AS one_day_click_conversion_value, MAX(video_views) AS video_views, MAX(p50_video_views) AS p50_video_views FROM `beastlife-wh-474411.maplemonk.beastlife_hourly_MARKETING_CONSOLIDATED` WHERE ACCOUNT_NAME = \"FACEBOOK\" AND DATE = CURRENT_DATE() GROUP BY 1, 2, 3, 4, 5, 6 ), shopify AS ( SELECT Order_Date, utm_campaign, utm_term, SUM( CASE WHEN DATE(Order_Date) >= DATE \'2025-09-22\' THEN (Selling_Price / 1.06) * 0.90 ELSE (Selling_Price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(selling_price) AS sell, COUNT(DISTINCT order_id) AS orders, SUM(quantity) * 0.90 AS quantity, COUNT(DISTINCT CASE WHEN new_customer_flag = \"Repeat\" THEN order_id END) * 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \"New\" THEN order_id END) * 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \"New\" THEN selling_price * 0.90 ELSE 0 END) AS new_customer_sales, SUM(CASE WHEN new_customer_flag = \"Repeat\" THEN selling_price * 0.90 ELSE 0 END) AS repeat_customer_sales, SUM(IF(cod_pp_flag = \"COD\", selling_price * 0.90, 0)) AS cod_sales, SUM(IF(cod_pp_flag = \"Prepaid\", selling_price * 0.90, 0)) AS prepaid_sales, SUM(IF(cod_pp_flag = \"Partial Paid\", selling_price * 0.90, 0)) AS partial_paid_sales, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"COD\" THEN order_id END) * 0.90 AS cod_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Prepaid\" THEN order_id END) * 0.90 AS prepaid_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Partial Paid\" THEN order_id END) * 0.90 AS partial_paid_orders FROM `beastlife-wh-474411.maplemonk.Hourly_D2C_master` WHERE channel IN ( \'meta\', \'META\', \'facebook\', \'FACEBOOK\', \'facebook_ads\', \'FACEBOOK_ADS\', \'meta-SiteLink\', \'META-SITELINK\' ) AND order_status = \"SHOPIFY_PROCESSED\" AND DATE(Order_Date) = CURRENT_DATE() GROUP BY 1, 2, 3 ) SELECT COALESCE(fb.`DATE`, shopify.Order_Date) AS DATE, fb.CAMPAIGN_NAME, fb.AD_NAME, fb.ADSET_NAME, CASE WHEN REGEXP_CONTAINS(fb.CAMPAIGN_NAME, r\'(^|[^A-Z])(ASC|ABO|CBO)([^A-Z]|$)\') THEN \'ASC\' ELSE \'NON ASC\' END AS ASC_type, SUM(fb.SPEND) AS total_spend, SUM(fb.IMPRESSIONS) AS total_impressions, SUM(fb.CLICKS) AS total_clicks, SUM(fb.Link_Clicks) AS total_Link_Clicks, SUM(fb.ADD_TO_CARTS) AS ADD_TO_CARTS, SUM(fb.ADD_TO_CART_VALUE) AS ADD_TO_CART_VALUE, SUM(fb.LANDING_PAGE_VIEWS) AS LANDING_PAGE_VIEWS, SUM(fb.INITIATE_CHECKOUTS) AS INITIATE_CHECKOUTS, SUM(fb.INITIATE_CHECKOUTS_VALUE) AS INITIATE_CHECKOUTS_VALUE, SUM(fb.one_day_click_conversions) AS one_day_click_conversions, SUM(fb.one_day_click_conversion_value) AS one_day_click_conversion_value, SUM(fb.video_views) AS video_views, SUM(fb.p50_video_views) AS p50_video_views, COALESCE(SUM(shopify.gross_sales), 0) AS total_gross_sales, COALESCE(SUM(shopify.sell), 0) AS total_sell, COALESCE(SUM(orders), 0) AS total_orders, COALESCE(SUM(shopify.repeat_orders), 0) AS total_repeat_orders, COALESCE(SUM(shopify.new_orders), 0) AS total_new_orders, COALESCE(SUM(shopify.new_customer_sales), 0) AS total_new_customer_sales, COALESCE(SUM(shopify.repeat_customer_sales), 0) AS total_repeat_customer_sales, COALESCE(SUM(shopify.cod_sales), 0) AS total_cod_sales, COALESCE(SUM(shopify.prepaid_sales), 0) AS total_prepaid_sales, COALESCE(SUM(shopify.partial_paid_sales), 0) AS total_partial_paid_sales, COALESCE(SUM(shopify.cod_orders), 0) AS total_cod_orders, COALESCE(SUM(shopify.prepaid_orders), 0) AS total_prepaid_orders, COALESCE(SUM(shopify.partial_paid_orders), 0) AS total_partial_paid_orders FROM fb FULL OUTER JOIN shopify ON fb.AD_ID = shopify.utm_term AND fb.DATE = shopify.Order_Date GROUP BY 1, 2, 3, 4 ORDER BY total_spend DESC ), mapped AS ( SELECT LOWER(TRIM(ad_name)) AS meta_ad_name, LOWER(TRIM(ProductSku_category)) AS meta_sku, LOWER(type_of_creative) AS Creative_Type, LOWER(influencer_type) AS Influencer_Type, LOWER(Script_type) AS Script_type, LOWER(face_value) AS face_value, LOWER(Creator_Type) AS Creator_Type, LOWER(Language) AS Language, LOWER(week_period) AS week_period, SUM(SAFE_CAST(Sku_count AS FLOAT64)) AS Sku_count FROM `beastlife-wh-474411.maplemonk.beastlife_db_MetaadsName` GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), catalog AS ( SELECT Category, SKU_Code, SKU_Type, Ingredients, Rev_Category, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, SUM(CAST(MRP AS NUMERIC)) AS MRP, SUM(CAST(MRP_Revised AS NUMERIC)) AS MRP_Revised FROM `maplemonk.MasterCatalogue` GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT(FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' ELSE \'Error\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), final AS ( SELECT * FROM shopy LEFT JOIN mapped ON LOWER(shopy.AD_NAME) = LOWER(mapped.meta_ad_name) ) SELECT * FROM final LEFT JOIN catalog ON REGEXP_REPLACE(UPPER(TRIM(final.meta_sku)), r\'[^A-Z0-9]\', \'\') = REGEXP_REPLACE(UPPER(TRIM(catalog.SKU_Code)), r\'[^A-Z0-9]\', \'\') LEFT JOIN calendar ON final.DATE = calendar.event_date UNION ALL (WITH shopy AS ( WITH fb AS ( SELECT DATE, CAMPAIGN_NAME, CAMPAIGN_ID, AD_NAME, AD_ID, ADSET_NAME, SUM(SPEND) AS SPEND, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS, SUM(Link_Clicks) AS Link_Clicks, SUM(ADD_TO_CARTS) AS ADD_TO_CARTS, SUM(ADD_TO_CART_VALUE) AS ADD_TO_CART_VALUE, SUM(LANDING_PAGE_VIEWS) AS LANDING_PAGE_VIEWS, SUM(INITIATE_CHECKOUTS) AS INITIATE_CHECKOUTS, SUM(INITIATE_CHECKOUTS_VALUE) AS INITIATE_CHECKOUTS_VALUE, SUM(one_day_click_conversions) AS one_day_click_conversions, SUM(one_day_click_conversion_value) AS one_day_click_conversion_value, SUM(video_views) AS video_views, SUM(p50_video_views) AS p50_video_views FROM `beastlife-wh-474411.maplemonk.beastlife_wh_474411_MARKETING_CONSOLIDATED` WHERE ACCOUNT_NAME = \"FACEBOOK\" AND DATE < CURRENT_DATE() GROUP BY 1, 2, 3, 4, 5, 6 ), shopify AS ( SELECT Order_Date, utm_campaign, utm_term, SUM( CASE WHEN DATE(Order_Date) >= DATE \'2025-09-22\' THEN (Selling_Price / 1.06) * 0.90 ELSE (Selling_Price / 1.18) * 0.90 END ) AS NSV, SUM(selling_price) * 0.90 AS gross_sales, SUM(selling_price) AS sell, COUNT(DISTINCT order_id) AS orders, SUM(quantity) * 0.90 AS quantity, COUNT(DISTINCT CASE WHEN new_customer_flag = \"Repeat\" THEN order_id END) * 0.90 AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \"New\" THEN order_id END) * 0.90 AS new_orders, SUM(CASE WHEN new_customer_flag = \"New\" THEN selling_price * 0.90 ELSE 0 END) AS new_customer_sales, SUM(CASE WHEN new_customer_flag = \"Repeat\" THEN selling_price * 0.90 ELSE 0 END) AS repeat_customer_sales, SUM(IF(cod_pp_flag = \"COD\", selling_price * 0.90, 0)) AS cod_sales, SUM(IF(cod_pp_flag = \"Prepaid\", selling_price * 0.90, 0)) AS prepaid_sales, SUM(IF(cod_pp_flag = \"Partial Paid\", selling_price * 0.90, 0)) AS partial_paid_sales, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"COD\" THEN order_id END) * 0.90 AS cod_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Prepaid\" THEN order_id END) * 0.90 AS prepaid_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Partial Paid\" THEN order_id END) * 0.90 AS partial_paid_orders FROM `beastlife-wh-474411.maplemonk.D2C_master` WHERE channel IN ( \'meta\', \'META\', \'facebook\', \'FACEBOOK\', \'facebook_ads\', \'FACEBOOK_ADS\', \'meta-SiteLink\', \'META-SITELINK\' ) AND order_status = \"SHOPIFY_PROCESSED\" AND DATE(Order_Date) < CURRENT_DATE() GROUP BY 1, 2, 3 ) SELECT COALESCE(fb.`DATE`, shopify.Order_Date) AS DATE, fb.CAMPAIGN_NAME, fb.AD_NAME, fb.ADSET_NAME, CASE WHEN REGEXP_CONTAINS(fb.CAMPAIGN_NAME, r\'(^|[^A-Z])(ASC|ABO|CBO)([^A-Z]|$)\') THEN \'ASC\' ELSE \'NON ASC\' END AS ASC_type, SUM(fb.SPEND) AS total_spend, SUM(fb.IMPRESSIONS) AS total_impressions, SUM(fb.CLICKS) AS total_clicks, SUM(fb.Link_Clicks) AS total_Link_Clicks, SUM(fb.ADD_TO_CARTS) AS ADD_TO_CARTS, SUM(fb.ADD_TO_CART_VALUE) AS ADD_TO_CART_VALUE,