CAST(MRP AS NUMERIC)) AS MRP, SUM(CAST(MRP_Revised AS NUMERIC)) AS MRP_Revised FROM `maplemonk.MasterCatalogue` GROUP BY 1, 2, 3, 4, 5, 6, 7, 8 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT(FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' ELSE \'Error\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), final AS ( SELECT * FROM shopy LEFT JOIN mapped ON LOWER(shopy.AD_NAME) = LOWER(mapped.meta_ad_name) ) SELECT * FROM final LEFT JOIN catalog ON REGEXP_REPLACE(UPPER(TRIM(final.meta_sku)), r\'[^A-Z0-9]\', \'\') = REGEXP_REPLACE(UPPER(TRIM(catalog.SKU_Code)), r\'[^A-Z0-9]\', \'\') LEFT JOIN calendar ON final.DATE = calendar.event_date) ), aggregated AS ( SELECT AD_NAME, DATE, CAMPAIGN_NAME, ADSET_NAME, ASC_type, Creative_Type, Influencer_Type, meta_sku, meta_ad_name, Rev_Category, Language, Creator_Type, Script_type, face_value, week_period, Category, SKU_Code, SKU_Type, Ingredients, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, MRP, MRP_Revised, Sku_count, event_date, Event, sub_event, DateAsInteger, DateNumber, Year, MonthNumber, YearMonthNumber, YearMonthShort, MonthNameShort, MonthNameLong, DayOfWeekNumber, DayOfWeek, DayOfWeekShort, Quarter, YearQuarter, WeekPeriod, SUM(total_spend) AS total_spend, SUM(total_impressions) AS total_impressions, SUM(total_clicks) AS total_clicks, SUM(total_Link_Clicks) AS total_Link_Clicks, SUM(total_orders) AS total_orders, SUM(total_gross_sales) AS total_gross_sales, SUM(total_sell) AS total_sell, SUM(ADD_TO_CARTS) AS ADD_TO_CARTS, SUM(ADD_TO_CART_VALUE) AS ADD_TO_CART_VALUE, SUM(LANDING_PAGE_VIEWS) AS LANDING_PAGE_VIEWS, SUM(INITIATE_CHECKOUTS) AS INITIATE_CHECKOUTS, SUM(INITIATE_CHECKOUTS_VALUE) AS INITIATE_CHECKOUTS_VALUE, SUM(one_day_click_conversions) AS one_day_click_conversions, SUM(one_day_click_conversion_value) AS one_day_click_conversion_value, SUM(video_views) AS video_views, SUM(p50_video_views) AS p50_video_views, SUM(total_repeat_orders) AS total_repeat_orders, SUM(total_new_orders) AS total_new_orders, SUM(total_new_customer_sales) AS total_new_customer_sales, SUM(total_repeat_customer_sales) AS total_repeat_customer_sales, SUM(total_cod_sales) AS total_cod_sales, SUM(total_prepaid_sales) AS total_prepaid_sales, SUM(total_partial_paid_sales) AS total_partial_paid_sales, SUM(total_cod_orders) AS total_cod_orders, SUM(total_prepaid_orders) AS total_prepaid_orders, SUM(total_partial_paid_orders) AS total_partial_paid_orders, SAFE_DIVIDE(SUM(total_clicks), SUM(total_impressions)) * 100 AS CTR, SAFE_DIVIDE(SUM(total_Link_Clicks), SUM(total_impressions)) * 100 AS Link_CTR FROM main_data GROUP BY AD_NAME, DATE, CAMPAIGN_NAME, ADSET_NAME, ASC_type, Creative_Type, Influencer_Type, meta_sku, meta_ad_name, Rev_Category, Language, Creator_Type, Script_type, face_value, week_period, Category, SKU_Code, SKU_Type, Ingredients, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, MRP, MRP_Revised, Sku_count, event_date, Event, sub_event, DateAsInteger, DateNumber, Year, MonthNumber, YearMonthNumber, YearMonthShort, MonthNameShort, MonthNameLong, DayOfWeekNumber, DayOfWeek, DayOfWeekShort, Quarter, YearQuarter, WeekPeriod ), ad_level_ctr AS ( SELECT AD_NAME, SUM(total_spend) AS ad_spend, SAFE_DIVIDE(SUM(total_clicks), SUM(total_impressions)) * 100 AS ad_ctr FROM aggregated GROUP BY AD_NAME HAVING SUM(total_spend) >= 2000 AND SAFE_DIVIDE(SUM(total_clicks), SUM(total_impressions)) * 100 > 0 ), ranked_ads AS ( SELECT AD_NAME, ad_ctr, RANK() OVER (ORDER BY ad_ctr DESC) AS ctr_rank_top, RANK() OVER (ORDER BY ad_ctr ASC) AS ctr_rank_bottom FROM ad_level_ctr ) SELECT a.*, r.ad_ctr, CASE WHEN r.ctr_rank_top <= 5 THEN \'Top 5\' WHEN r.ctr_rank_bottom <= 5 THEN \'Bottom 5\' ELSE \'Middle\' END AS CTR_Category FROM aggregated a LEFT JOIN ranked_ads r ON a.AD_NAME = r.AD_NAME",
